import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Atlas region dimensions (source rect: 512 x 320)
  const aspect = 512 / 320; // 1.6
  const width = aspect; // keep height = 1 unit for simplicity
  const height = 1;

  // Geometry and material
  const geometry = new PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial();

  // Load texture (if provided)
  const texturePromise = config.imageUrl
    ? ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
        material.map = texture(tex, uv());
        material.needsUpdate = true;
        // Store reference for cleanup
        root.userData._loadedTexture = tex;
      })
    : Promise.resolve();

  // Mesh (billboard toward camera)
  const mesh = new Mesh(geometry, material);
  mesh.onBeforeRender = (_, __, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  root.add(mesh);

  // No interactions; empty handler stub
  root.userData.handlers = {};

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();

    // Dispose loaded texture if any
    if (root.userData._loadedTexture) {
      root.userData._loadedTexture.dispose();
      delete root.userData._loadedTexture;
    }

    // Kill any GSAP timelines that might have been created elsewhere
    if (root.userData._timelines) {
      root.userData._timelines.forEach((tl) => tl.kill());
    }
  };

  // Store any timelines (none for this node but placeholder for future primitives)
  root.userData._timelines = [];

  return root;
}
